import { health_data_settings_data, health_data_settings_data_Item } from '../../api/api-types'

/** Field ids that the CSX API deserializes as DateTime (not numeric). */
const HEALTH_DATA_DATE_FIELD_IDS = new Set<string>(['LastMenstrualPeriod', 'ExpectedDateOfConfinement']);

function isHealthDataDateItem(item: health_data_settings_data_Item): boolean {
  if (HEALTH_DATA_DATE_FIELD_IDS.has(item.id)) {
    return true;
  }
  const t = (item.dataType || '').toLowerCase();
  return t.includes('date') || t === 'datetime';
}

function encodeHealthDataValueForApi(item: health_data_settings_data_Item): string | number | null {
  const raw = item.value;
  if (raw === undefined || raw === null || String(raw).trim() === '') {
    return null;
  }
  if (isHealthDataDateItem(item)) {
    const s = String(raw).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
      return s;
    }
    if (/^\d{4}-\d{2}-\d{2}T/.test(s)) {
      return s.slice(0, 10);
    }
    return s;
  }
  const n = parseFloat(String(raw));
  return Number.isNaN(n) ? null : n;
}

function patchHealthDataSettingItem(
  settings: health_data_settings_data[],
  group: number,
  label: string,
  value: string | undefined | null,
): health_data_settings_data[] {
  return settings.map((g, gi) => {
    if (gi !== group) {
      return g;
    }
    return {
      ...g,
      items: g.items.map((row) => {
        if (row.id !== label) {
          return row;
        }
        const nextRaw = value === undefined || value === null ? '' : value;
        const nextVal =
          typeof nextRaw === 'string' && nextRaw.endsWith('.') && !isHealthDataDateItem(row)
            ? `${nextRaw}0`
            : nextRaw;
        return { ...row, value: nextVal };
      }),
    };
  });
}

